param([Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$CandidateRoot,[Parameter(Mandatory)][string]$SandboxRoot)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
function VerifyBundleIdentity {
    $bundleRoot=[IO.Path]::GetFullPath((Split-Path -Parent $PSCommandPath)).TrimEnd('\');$manifestPath=Join-Path $bundleRoot 'BUNDLE.MANIFEST.json';$expectedPaths=@('Test-EngineLabNetworkReleaseCandidate.ps1','test-engine-lab-network-release-candidate-verifier-hostile.ps1','test-engine-lab-network-release-candidate-verifier.ps1');$expectedTree=@('BUNDLE.MANIFEST.json')+$expectedPaths
    if([IO.Path]::GetFileName($bundleRoot)-cnotmatch'^phaseb-[0-9A-F]{64}$'-or-not(Test-Path -LiteralPath $manifestPath -PathType Leaf)){throw 'Verifier bundle root/manifest rejected.'};if(((Get-Item -LiteralPath $bundleRoot -Force).Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw 'Verifier bundle reparse rejected.'};$actualTree=@(Get-ChildItem -LiteralPath $bundleRoot -Force);if($actualTree.Count-ne4-or@($actualTree|Where-Object PSIsContainer).Count-or@(Compare-Object -CaseSensitive ($expectedTree|Sort-Object) @($actualTree.Name|Sort-Object)).Count){throw 'Verifier bundle exact tree rejected.'}
    $manifestBytes=[IO.File]::ReadAllBytes($manifestPath);if($manifestBytes.Length-ge3-and$manifestBytes[0]-eq0xEF-and$manifestBytes[1]-eq0xBB-and$manifestBytes[2]-eq0xBF){throw 'Verifier bundle manifest BOM rejected.'};$raw=[Text.Encoding]::UTF8.GetString($manifestBytes);if($raw.Contains("`r")){throw 'Verifier bundle manifest canonical LF rejected.'};$document=[Text.Json.JsonDocument]::Parse($raw);try{$names=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($property in $document.RootElement.EnumerateObject()){if(-not$names.Add($property.Name)){throw 'Verifier bundle manifest duplicate field rejected.'}};if(-not([Collections.Generic.HashSet[string]]::new([string[]]@('schemaVersion','algorithm','files','bundleSha256'),[StringComparer]::Ordinal)).SetEquals($names)){throw 'Verifier bundle manifest schema rejected.'};foreach($item in $document.RootElement.GetProperty('files').EnumerateArray()){$itemNames=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($property in $item.EnumerateObject()){if(-not$itemNames.Add($property.Name)){throw 'Verifier bundle file duplicate field rejected.'}};if(-not([Collections.Generic.HashSet[string]]::new([string[]]@('path','size','sha256'),[StringComparer]::Ordinal)).SetEquals($itemNames)){throw 'Verifier bundle file schema rejected.'}}}finally{$document.Dispose()};$manifest=$raw|ConvertFrom-Json -DateKind String
    if($manifest.schemaVersion-isnot[int]-and$manifest.schemaVersion-isnot[long]){throw 'Verifier bundle schema type rejected.'};if([long]$manifest.schemaVersion-ne1-or$manifest.algorithm-cne'sha256-utf8-ordinal-path-size-hash-lf-v1'-or$manifest.files-isnot[array]-or$manifest.files.Count-ne3-or$manifest.bundleSha256-cnotmatch'^[0-9a-f]{64}$'){throw 'Verifier bundle manifest identity rejected.'};$rows=[Collections.Generic.List[string]]::new();for($i=0;$i-lt3;$i++){$item=$manifest.files[$i];$relative=[string]$item.path;if($relative-cne$expectedPaths[$i]-or[IO.Path]::IsPathRooted($relative)-or$relative.Contains('/')-or$relative.Contains('\')-or$relative.Contains(':')-or$relative-in@('.','..')){throw 'Verifier bundle path/order rejected.'};if($item.size-isnot[int]-and$item.size-isnot[long]){throw 'Verifier bundle size type rejected.'};$path=Join-Path $bundleRoot $relative;if(-not(Test-Path -LiteralPath $path -PathType Leaf)-or((Get-Item -LiteralPath $path -Force).Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or@(Get-Item -LiteralPath $path -Stream *|Where-Object Stream -ne ':$DATA').Count){throw 'Verifier bundle file safety rejected.'};$length=[int64](Get-Item -LiteralPath $path).Length;$stream=[IO.File]::Open($path,'Open','Read','Read');try{$sha=[Security.Cryptography.SHA256]::Create();try{$hash=([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}finally{$stream.Dispose()};if([long]$item.size-ne$length-or$item.sha256-cne$hash){throw 'Verifier bundle file size/hash rejected.'};$rows.Add("$relative|$length|$hash")};$sha=[Security.Cryptography.SHA256]::Create();try{$digest=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(($rows-join"`n")+"`n")))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};if($manifest.bundleSha256-cne$digest-or[IO.Path]::GetFileName($bundleRoot)-cne('phaseb-'+$digest.ToUpperInvariant())){throw 'Verifier bundle digest/root binding rejected.'}
}
VerifyBundleIdentity
$verifier=Join-Path (Split-Path -Parent $PSCommandPath) 'Test-EngineLabNetworkReleaseCandidate.ps1'
$tokens=$null;$errors=$null;[Management.Automation.Language.Parser]::ParseFile($verifier,[ref]$tokens,[ref]$errors)|Out-Null;if($errors.Count){throw ($errors.Message-join'; ')}
function CandidateDigest([string]$Root){$full=[IO.Path]::GetFullPath($Root).TrimEnd('\');$rows=@(Get-ChildItem $full -Force -Recurse|ForEach-Object{$relative=$_.FullName.Substring($full.Length+1).Replace('\','/');$kind=if($_.PSIsContainer){'D'}else{'F'};$row=$kind+':'+$relative+':'+([int64]$_.Attributes);if(-not$_.PSIsContainer){$streams=@(Get-Item $_.FullName -Stream *|ForEach-Object{$_.Stream+':'+$_.Length}|Sort-Object);$row+=':'+($_.Length)+':'+(Get-FileHash $_.FullName).Hash+':'+($streams-join',')};$row}|Sort-Object);$sha=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(($rows-join"`n"))))).Replace('-','')}finally{$sha.Dispose()}}
$baseline=CandidateDigest $CandidateRoot
$output=Join-Path $SandboxRoot 'verify-engine-lab-v254-selftest';if(Test-Path $output){Remove-Item $output -Recurse -Force};&$verifier -ProjectRoot $ProjectRoot -CandidateRoot $CandidateRoot -VerificationRoot $output;if( -not (Test-Path (Join-Path $output 'candidate-verification.json'))){throw 'Verifier did not produce receipt.'}
foreach($label in @('live-normal-capture','live-gbv-capture')){$recordPath=Join-Path $output ('logs/'+$label+'.command.json');if(-not(Test-Path $recordPath -PathType Leaf)){throw "Missing live command evidence: $label"};$record=Get-Content $recordPath -Raw|ConvertFrom-Json;if($record.schemaVersion-ne2-or$record.label-cne$label-or$record.inputs.Count-ne2-or@($record.inputs|Where-Object{$_.sha256Before-cne$_.sha256After}).Count){throw "Live input evidence rejected: $label"}}
if((CandidateDigest $CandidateRoot)-cne$baseline){throw 'Verifier modified candidate.'}
Write-Host 'ENGINE_LAB_CANDIDATE_VERIFIER_SELF_TEST_PASS'
